// nhlib.lua: embedded from the recorder's data directory (generated by transpiler/emit/data.mjs). Do not edit.
export default "-- NetHack nhlib.lua\t$NHDT-Date: 1652196140 2022/05/10 15:22:20 $  $NHDT-Branch: NetHack-3.7 $:$NHDT" +
    "-Revision: 1.4 $\n--\tCopyright (c) 2021 by Pasi Kallinen\n-- NetHack may be freely redistributed.  See" +
    " license for details.\n-- compatibility shim\nmath.random = function(...)\n   local arg = {...};\n   if " +
    "(#arg == 1) then\n      return 1 + nh.rn2(arg[1]);\n   elseif (#arg == 2) then\n      return nh.random(" +
    "arg[1], arg[2] + 1 - arg[1]);\n   else\n      -- we don't support reals\n      error(\"NetHack math.rand" +
    "om requires at least one parameter\");\n   end\nend\n\nfunction shuffle(list)\n   for i = #list, 2, -1 do\n" +
    "      local j = math.random(i)\n      list[i], list[j] = list[j], list[i]\n   end\nend\n\nalign = { \"law\"" +
    ", \"neutral\", \"chaos\" };\nshuffle(align);\n\n-- d(2,6) = 2d6\n-- d(20) = 1d20 (single argument = implicit" +
    " 1 die)\nfunction d(dice, faces)\n   if (faces == nil) then\n      -- 1-arg form: argument \"dice\" is ac" +
    "tually the number of faces\n      return math.random(1, dice)\n   else\n      local sum = 0\n      for i" +
    "=1,dice do\n         sum = sum + math.random(1, faces)\n      end\n      return sum\n   end\nend\n\n-- perc" +
    "ent(20) returns true 20% of the time\nfunction percent(threshold)\n   return math.random(0, 99) < thre" +
    "shold\nend\n\nfunction monkfoodshop()\n   if (u.role == \"Monk\") then\n      return \"health food shop\";\n  " +
    " end\n   return \"food shop\";\nend\n\n-- tweaks to gehennom levels; might add random lava pools or\n-- a l" +
    "ava river.\n-- protected_area is a selection where no changes will be done.\nfunction hell_tweaks(prot" +
    "ected_area)\n   local liquid = \"L\";\n   local ground = \".\";\n   local n_prot = protected_area:numpoints" +
    "();\n   local prot = protected_area:negate();\n\n   -- random pools\n   if (percent(20 + u.depth)) then\n" +
    "      local pools = selection.new();\n      local maxpools = 5 + math.random(u.depth);\n      for i = " +
    "1, maxpools do\n         pools:set();\n      end\n      pools = pools | selection.grow(selection.set(se" +
    "lection.new()), \"west\")\n      pools = pools | selection.grow(selection.set(selection.new()), \"north\"" +
    ")\n      pools = pools | selection.grow(selection.set(selection.new()), \"random\")\n\n      pools = pool" +
    "s & prot;\n\n      if (percent(80)) then\n         local poolground = pools:clone():grow(\"all\") & prot;" +
    "\n         local pval = math.random(1, 8) * 10;\n         des.terrain(poolground:percentage(pval), gro" +
    "und)\n      end\n      des.terrain(pools, liquid)\n   end\n\n   -- river\n   if (percent(50)) then\n      l" +
    "ocal allrivers = selection.new();\n      local reqpts = ((nhc.COLNO * nhc.ROWNO) - n_prot) / 12; -- #" +
    " of lava pools required\n      local rpts = 0;\n      local rivertries = 0;\n\n      repeat\n            " +
    "local floor = selection.match(ground);\n            local a = selection.rndcoord(floor);\n            " +
    "local b = selection.rndcoord(floor);\n            local lavariver = selection.randline(selection.new(" +
    "), a.x, a.y, b.x, b.y, 10);\n\n            if (percent(50)) then\n               lavariver = selection." +
    "grow(lavariver, \"north\");\n            end\n            if (percent(50)) then\n               lavariver" +
    " = selection.grow(lavariver, \"west\");\n            end\n            allrivers = allrivers | lavariver;" +
    "\n            allrivers = allrivers & prot;\n\n            rpts = allrivers:numpoints();\n            ri" +
    "vertries = rivertries + 1;\n      until ((rpts > reqpts) or (rivertries > 7));\n\n      if (percent(60)" +
    ") then\n         local prc = 10 * math.random(1, 6);\n         local riverbanks = selection.grow(allri" +
    "vers);\n         riverbanks = riverbanks & prot;\n         des.terrain(selection.percentage(riverbanks" +
    ", prc), ground);\n      end\n\n      des.terrain(allrivers, liquid);\n   end\n\n   -- replacing some walls" +
    " with boulders\n   if (percent(20)) then\n      local amount = 3 * math.random(1, 8);\n      local bwal" +
    "ls = selection.match([[.w.]]):percentage(amount) | selection.match(\".\\nw\\n.\"):percentage(amount);\n  " +
    "    bwalls = bwalls & prot;\n      bwalls:iterate(function (x,y)\n            des.terrain(x, y, \".\");\n" +
    "            des.object(\"boulder\", x, y);\n      end);\n   end\n\n   -- replacing some walls with iron ba" +
    "rs\n   if (percent(20)) then\n      local amount = 3 * math.random(1, 8);\n      local fwalls = selecti" +
    "on.match([[.w.]]):percentage(amount) | selection.match(\".\\nw\\n.\"):percentage(amount);\n      fwalls =" +
    " fwalls:grow() & selection.match(\"w\") & prot;\n      des.terrain(fwalls, \"F\");\n   end\n\nend\n\n-- pline " +
    "with variable number of arguments\nfunction pline(fmt, ...)\n   nh.pline(string.format(fmt, table.unpa" +
    "ck({...})));\nend\n\n-- wrapper to make calling from nethack core easier\nfunction nh_set_variables_stri" +
    "ng(key, tbl)\n   return \"nh_lua_variables[\\\"\" .. key .. \"\\\"]=\" .. table_stringify(tbl) .. \";\";\nend\n\n-" +
    "- wrapper to make calling from nethack core easier\nfunction nh_get_variables_string(tbl)\n   return \"" +
    "return \" .. table_stringify(tbl) .. \";\";\nend\n\n-- return the (simple) table tbl converted into a stri" +
    "ng\nfunction table_stringify(tbl)\n   local str = \"\";\n   for key, value in pairs(tbl) do\n      local t" +
    "yp = type(value);\n      if (typ == \"table\") then\n         str = str .. \"[\\\"\" .. key .. \"\\\"]=\" .. tab" +
    "le_stringify(value);\n      elseif (typ == \"string\") then\n         str = str .. \"[\\\"\" .. key .. \"\\\"]=" +
    "[[\" .. value .. \"]]\";\n      elseif (typ == \"boolean\") then\n         str = str .. \"[\\\"\" .. key .. \"\\\"" +
    "]=\" .. tostring(value);\n      elseif (typ == \"number\") then\n         str = str .. \"[\\\"\" .. key .. \"\\" +
    "\"]=\" .. value;\n      elseif (typ == \"nil\") then\n         str = str .. \"[\\\"\" .. key .. \"\\\"]=nil\";\n   " +
    "   end\n      str = str .. \",\";\n   end\n   -- pline(\"table_stringify:(%s)\", str);\n   return \"{\" .. str" +
    " .. \"}\";\nend\n\n--\n-- TUTORIAL\n--\n\n-- extended commands NOT available in tutorial\nlocal tutorial_black" +
    "list_commands = {\n   [\"save\"] = true,\n};\n\nfunction tutorial_cmd_before(cmd)\n   -- nh.pline(\"TUT:cmd_" +
    "before:\" .. cmd);\n\n   if (tutorial_blacklist_commands[cmd]) then\n      return false;\n   end\n   retur" +
    "n true;\nend\n\nfunction tutorial_enter()\n   -- nh.pline(\"TUT:enter\");\n\n   -- add the tutorial branch c" +
    "allbacks\n   nh.callback(\"cmd_before\", \"tutorial_cmd_before\");\n   nh.callback(\"end_turn\", \"tutorial_t" +
    "urn\");\n\n   -- save state for later restore\n   nh.gamestate();\nend\n\nfunction tutorial_leave()\n   -- n" +
    "h.pline(\"TUT:leave\");\n\n   -- remove the tutorial branch callbacks\n   nh.callback(\"cmd_before\", \"tuto" +
    "rial_cmd_before\", true);\n   nh.callback(\"end_turn\", \"tutorial_turn\", true);\n\n   -- restore state for" +
    " regular play\n   nh.gamestate(true);\nend\n\nlocal tutorial_events = {\n   {\n      func = function()\n   " +
    "      if (u.uhunger < 148) then\n            local o = obj.new(\"blessed food ration\");\n            o:" +
    "placeobj(u.ux, u.uy);\n            nh.pline(\"Looks like you're getting hungry.  You'll starve to deat" +
    "h, unless you eat something.\", true);\n            nh.pline(\"Comestibles are eaten with '\" .. nh.ecke" +
    "y(\"eat\") .. \"'\", true);\n            return true;\n         end\n      end\n   },\n};\n\nfunction tutorial_" +
    "turn()\n   for k, v in pairs(tutorial_events) do\n      if ((v.ucoord and u.ux == v.ucoord[1] + 3 and " +
    "u.uy == v.ucoord[2] + 3)\n         or (v.ucoord == nil)) then\n         if (v.func() or v.remove) then" +
    "\n            tutorial_events[k] = nil;\n         end\n      end\n   end\n   -- nh.pline(\"TUT:turn\");\nend" +
    "\n";
